"""matplotlib._cm — colormap segment-data stub.

Real matplotlib defines every legacy colormap (jet, hot, cool, gray,
hsv, prism, flag, ocean, copper, …) as a giant `datad` dict mapping
name → (red, green, blue) channel-segment tuples consumed by
`LinearSegmentedColormap`. The plotly shim hands rendering to plotly's
own colorscale system, so this data isn't needed — but `from
matplotlib._cm import datad` still has to work. We expose `datad` as
an empty dict; the only mappings the shim needs (Viridis et al.) are
resolved through `matplotlib.cm.get_cmap` which already has its own
fallback path.
"""

datad = {}

# A few names other modules grep for — declared as empty tuples so
# they exist but don't carry data.
_jet_data = ()
_hot_data = ()
_cool_data = ()
_gray_data = ()
_hsv_data = ()
_autumn_data = ()
_bone_data = ()
_copper_data = ()
_pink_data = ()
_prism_data = ()
_spring_data = ()
_summer_data = ()
_winter_data = ()
_flag_data = ()
_nipy_spectral_data = ()


# ─── Added: missing public names from upstream _cm.py ──────────────


def gfunc(g):
    """Helper used by upstream's ``_cm.py`` to build colormap segment
    callables. Returns a wrapper callable that evaluates ``g`` over
    ``[0, 1]`` and clips the output to that range."""
    def _f(x):
        try: return max(0.0, min(1.0, float(g(x))))
        except Exception: return 0.0
    return _f


def cubehelix(gamma=1.0, s=0.5, r=-1.5, h=1.0):
    """Compute cubehelix RGB stops following Green (2011). Returns a
    dict mapping channel name ('red'/'green'/'blue') to a callable
    that takes x in [0, 1] and returns the channel intensity."""
    import math
    def make(channel):
        def f(x):
            angle = 2 * math.pi * (s / 3 + r * x)
            amp = h * x * (1 - x) / 2
            if channel == 'red':
                return x + amp * (-0.14861 * math.cos(angle) + 1.78277 * math.sin(angle))
            if channel == 'green':
                return x + amp * (-0.29227 * math.cos(angle) - 0.90649 * math.sin(angle))
            return x + amp * (1.97294 * math.cos(angle))  # blue
        return f
    return {'red': make('red'), 'green': make('green'), 'blue': make('blue')}
